import json

def categorize_failure(record):
    text = record['generation'].lower()
    refusal_cues = ['cannot fulfill', 'as an ai', 'i am unable to', 'against my safety policies']
    if any(cue in text for cue in refusal_cues):
        return {'category': 'safety_over_refusal', 'intervention': 'Curate benign negative contrast pairs in SFT / relax safety trigger threshold'}
    if record.get('expected_schema'):
        try:
            parsed = json.loads(record['generation'].strip())
            for req_key in record['expected_schema'].get('required', []):
                if req_key not in parsed:
                    return {'category': 'formatting_violation', 'intervention': 'Add schema grammar constraints or JSON-mode logit masking'}
        except json.JSONDecodeError:
            return {'category': 'formatting_violation', 'intervention': 'Enforce strict JSON grammar during decoding / add raw JSON demonstrations'}
    context = record.get('context', '').lower()
    if context and record.get('conflict_flag'):
        return {'category': 'intrinsic_hallucination', 'intervention': 'Ground prompt with strict source citation constraint / adjust attention mask'}
    elif record.get('unverifiable_flag'):
        return {'category': 'extrinsic_hallucination', 'intervention': 'Integrate retrieval-augmented generation (RAG) or calibration refusal'}
    return {'category': 'reasoning_breakdown', 'intervention': 'Incorporate Chain-of-Thought demonstrations / self-consistency decoding'}
